#define INIT_CLASS_IID
#include "native_observer_request.hpp"
#include <iostream>
int main(int argc,char** argv){try{using namespace cs80_observer;require(argc==3,"probe args");auto q=request::read(argv[1],argv[2]);auto id=cs80_identity::VerifiedIdentity::verify(q.identity,q.caps);std::cout<<id->expectedManifestDigest()<<'\n'<<id->evidenceDigest()<<'\n';ConnectedParameterRoster roster;for(const auto& e:sourceParameterExpectations())roster.ids.push_back(e.info.id);roster.declaredCount=roster.ids.size();auto plan=workload_detail::planFromRoster(q.workload,roster);plan.render.topology=q.topology;auto bytes=packed_filter_workload::encode_draft(q.workload);const char* h="0123456789abcdef";for(auto b:bytes)std::cout<<h[b>>4]<<h[b&15];std::cout<<'\n';for(const auto& b:{encodeFlushProtocol(plan.initial),encodeFlushProtocol(plan.alter),encodeRenderProtocol(plan.render)})std::cout<<cs80_identity::detail::digest(std::string(reinterpret_cast<const char*>(b.data.data()),b.data.size()))<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
